CREATE TABLE `incidencias` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `id_trampa` int(11) unsigned DEFAULT NULL,
  `sede_id` int(11) unsigned NOT NULL,
  `fecha` datetime NOT NULL,
  `tipo_plaga` varchar(100) NOT NULL,
  `tipo_insecto` varchar(50) DEFAULT NULL,
  `cantidad_organismos` varchar(11) DEFAULT NULL,
  `tipo_incidencia` varchar(100) DEFAULT NULL,
  `notas` text DEFAULT NULL,
  `inspector` varchar(255) NOT NULL,
  `plano_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `incidencias_id_trampa_foreign` (`id_trampa`),
  KEY `fk_sede_incidencias` (`sede_id`),
  CONSTRAINT `fk_sede_incidencias` FOREIGN KEY (`sede_id`) REFERENCES `sedes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `incidencias_id_trampa_foreign` FOREIGN KEY (`id_trampa`) REFERENCES `trampas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8769 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


